import { Component } from "solid-js";
import { JSX } from "solid-js/jsx-runtime";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { useImageCache } from "#core/ui-next/components/image-cache.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface YieldDeltaProps extends JSX.HTMLAttributes<HTMLDivElement> {
	yieldIconSrc: string;
	yieldTotal: number;
	yieldDelta: number;
}

const YieldDeltaSymbol = Symbol();
export const YieldDeltaComponent: Component<YieldDeltaProps> = (props) => {
	const images = {
		positiveYieldCSS: "url(blp:yield_container_positive)",
		negativeYieldCSS: "url(blp:yield_container_negative)",
		neutralYieldCSS: "url(blp:yield_container_neutral)",
	};
	const imageCache = useImageCache();
	imageCache.registerImages(YieldDeltaSymbol, Object.values(images));

	return (
		<div
			class="flex flex-col"
			classList={props.classList}
			data-name="Yield-Delta"
		>
			<div
				class={"w-11 flex flex-row justify-center mb-1 font-fit-shrink"}
				classList={{
					"text-positive": props.yieldDelta > 0,
					"text-negative": props.yieldDelta < 0,
					hidden: props.yieldDelta === 0,
				}}
				style={{
					"background-color": "rgba(0,0,0,0.3)",
				}}
			>
				{props.yieldDelta}
			</div>
			<div
				class="w-11 h-24"
				style={{
					"border-image-source":
						props.yieldDelta > 0
							? images.positiveYieldCSS
							: props.yieldDelta < 0
								? images.negativeYieldCSS
								: images.neutralYieldCSS,
					"border-image-slice": "17 21 fill",
					"border-image-width": "17px 21px",
				}}
			>
				<div class="flex flex-col justify-center items-center size-full font-fit-shrink">
					<Icon
						class="size-8 mt-1 mb-1"
						name={props.yieldIconSrc}
						isUrl={true}
					/>
					{props.yieldTotal}
				</div>
			</div>
		</div>
	);
};

export const YieldDelta = ComponentRegistry.register({
	name: "YieldDelta",
	createInstance: YieldDeltaComponent,
});
